import { test, expect } from '@playwright/test';

const FINGERPRINT_HEADER = { 'x-browser-fingerprint': 'qa-fp-hardened-001' };
const WHITESPACE_FP_HEADER = { 'x-browser-fingerprint': '   ' };

test.describe('Community API Contracts (Hardened)', () => {
  test('POST /api/v1/posts validates auth, whitespace, missing fields, and publishes content', async ({ request }) => {
    const missingAuthRes = await request.post('/api/v1/posts', { data: { content: 'No auth' } });
    expect(missingAuthRes.status()).toBe(401);
    expect(JSON.stringify(await missingAuthRes.json())).toContain('401_UNAUTHORIZED');

    const blankAuthRes = await request.post('/api/v1/posts', {
      headers: WHITESPACE_FP_HEADER,
      data: { content: 'Blank auth' },
    });
    expect(blankAuthRes.status()).toBe(401);
    expect(JSON.stringify(await blankAuthRes.json())).toContain('401_UNAUTHORIZED');

    for (const invalidPayload of [{ content: '' }, { content: '    ' }, {}]) {
      const invalidRes = await request.post('/api/v1/posts', {
        headers: FINGERPRINT_HEADER,
        data: invalidPayload,
      });
      expect(invalidRes.status()).toBe(400);
      expect(JSON.stringify(await invalidRes.json())).toContain('400_INVALID_CONTENT');
    }

    const okRes = await request.post('/api/v1/posts', {
      headers: FINGERPRINT_HEADER,
      data: { content: `Hardened API Post ${Date.now()}` },
    });
    expect([200, 201]).toContain(okRes.status());
    const okBody = await okRes.json();
    expect(typeof okBody.id).toBe('string');
    expect(okBody.id.length).toBeGreaterThan(0);
    expect(typeof okBody.created_at).toBe('string');
  });

  test('GET /api/v1/feed enforces pagination boundaries and cursor consistency', async ({ request }) => {
    await request.post('/api/v1/posts', {
      headers: FINGERPRINT_HEADER,
      data: { content: `Pagination Seed A ${Date.now()}` },
    });
    await request.post('/api/v1/posts', {
      headers: FINGERPRINT_HEADER,
      data: { content: `Pagination Seed B ${Date.now()}` },
    });

    const feedRes = await request.get('/api/v1/feed', {
      headers: FINGERPRINT_HEADER,
      params: { limit: 1 },
    });
    expect(feedRes.status()).toBe(200);
    const feedBody = await feedRes.json();
    expect(Array.isArray(feedBody.posts)).toBe(true);
    expect(feedBody.posts.length).toBeLessThanOrEqual(1);
    expect(typeof feedBody.next_cursor).toBe('string');

    if (feedBody.posts.length > 0) {
      const firstPost = feedBody.posts[0];
      expect(typeof firstPost.id).toBe('string');
      expect(typeof firstPost.content).toBe('string');
      expect(typeof firstPost.user_id).toBe('string');

      if (feedBody.next_cursor) {
        const nextRes = await request.get('/api/v1/feed', {
          headers: FINGERPRINT_HEADER,
          params: { cursor: feedBody.next_cursor, limit: 5 },
        });
        expect(nextRes.status()).toBe(200);
        const nextBody = await nextRes.json();
        expect(Array.isArray(nextBody.posts)).toBe(true);
        expect(nextBody.posts.length).toBeLessThanOrEqual(5);
        const nextIds = nextBody.posts.map((p: { id: string }) => p.id);
        expect(nextIds).not.toContain(firstPost.id);
      }
    }
  });

  test('POST /api/v1/messages guarantees target user via seed and rejects invalid/missing recipients', async ({ request }) => {
    const unauthMsgRes = await request.post('/api/v1/messages', {
      data: { recipient_id: 'any-user', content: 'Hi' },
    });
    expect([401, 403]).toContain(unauthMsgRes.status());

    const notFoundRes = await request.post('/api/v1/messages', {
      headers: FINGERPRINT_HEADER,
      data: { recipient_id: 'non-existent-user-99999', content: 'Hi' },
    });
    expect(notFoundRes.status()).toBe(404);
    expect(JSON.stringify(await notFoundRes.json())).toContain('404_USER_NOT_FOUND');

    const emptyMsgRes = await request.post('/api/v1/messages', {
      headers: FINGERPRINT_HEADER,
      data: { recipient_id: 'non-existent-user-99999', content: '   ' },
    });
    expect([400, 404]).toContain(emptyMsgRes.status());

    await request.post('/api/v1/posts', {
      headers: FINGERPRINT_HEADER,
      data: { content: `Seed User Post ${Date.now()}` },
    });
    const feedRes = await request.get('/api/v1/feed', {
      headers: FINGERPRINT_HEADER,
      params: { limit: 1 },
    });
    expect(feedRes.status()).toBe(200);
    const feedBody = await feedRes.json();
    expect(feedBody.posts.length).toBeGreaterThan(0);
    const targetUserId = feedBody.posts[0].user_id;

    const msgRes = await request.post('/api/v1/messages', {
      headers: FINGERPRINT_HEADER,
      data: { recipient_id: targetUserId, content: 'Hello via Hardened E2E' },
    });
    expect([200, 201]).toContain(msgRes.status());
    const msgBody = await msgRes.json();
    expect(typeof msgBody.message_id).toBe('string');
    expect(msgBody.message_id.length).toBeGreaterThan(0);
  });

  test('POST /api/v1/posts handles concurrent requests without ID collisions', async ({ request }) => {
    const requests = Array.from({ length: 5 }, (_, idx) =>
      request.post('/api/v1/posts', {
        headers: FINGERPRINT_HEADER,
        data: { content: `Concurrent Post ${idx} ${Date.now()}` },
      })
    );
    const responses = await Promise.all(requests);
    const ids = new Set<string>();
    for (const res of responses) {
      expect([200, 201]).toContain(res.status());
      const body = await res.json();
      expect(typeof body.id).toBe('string');
      ids.add(body.id);
    }
    expect(ids.size).toBe(5);
  });

  test('POST and GET /api/v1/posts/:postId/comments validates auth, empty content, and retrieves comments thread', async ({ request }) => {
    const seedRes = await request.post('/api/v1/posts', {
      headers: FINGERPRINT_HEADER,
      data: { content: `Comment Target Post ${Date.now()}` },
    });
    expect([200, 201]).toContain(seedRes.status());
    const seedBody = await seedRes.json();
    const targetPostId = seedBody.id;

    const unauthRes = await request.post(`/api/v1/posts/${targetPostId}/comments`, {
      data: { content: 'No auth comment' },
    });
    expect(unauthRes.status()).toBe(401);

    const emptyRes = await request.post(`/api/v1/posts/${targetPostId}/comments`, {
      headers: FINGERPRINT_HEADER,
      data: { content: '   ' },
    });
    expect(emptyRes.status()).toBe(400);

    const notFoundRes = await request.post('/api/v1/posts/non-existent-post-id/comments', {
      headers: FINGERPRINT_HEADER,
      data: { content: 'Valid comment' },
    });
    expect(notFoundRes.status()).toBe(404);

    const commentText = `Awesome X reply ${Date.now()}`;
    const okRes = await request.post(`/api/v1/posts/${targetPostId}/comments`, {
      headers: FINGERPRINT_HEADER,
      data: { content: commentText },
    });
    expect([200, 201]).toContain(okRes.status());
    const okBody = await okRes.json();
    expect(okBody.content).toBe(commentText);
    expect(okBody.post_id).toBe(targetPostId);
    expect(typeof okBody.id).toBe('string');

    const listRes = await request.get(`/api/v1/posts/${targetPostId}/comments`, {
      headers: FINGERPRINT_HEADER,
    });
    expect(listRes.status()).toBe(200);
    const listBody = await listRes.json();
    expect(Array.isArray(listBody.comments)).toBe(true);
    const found = listBody.comments.some((c: { id: string; content: string }) => c.id === okBody.id);
    expect(found).toBe(true);
  });
});

test.describe('Community Web E2E (Hardened)', () => {
  test('User publishes post with whitespace guard, double-click prevention, and reload persistence', async ({ page }) => {
    await page.goto('/');
    const postInput = page.getByRole('textbox', { name: /发帖|动态|说点什么|post|content/i });
    const publishButton = page.getByRole('button', { name: /发布|发送|post|publish/i });
    await expect(postInput).toBeVisible();

    await postInput.fill('   ');
    const isDisabled = await publishButton.isDisabled();
    if (!isDisabled) {
      await publishButton.click();
      await expect(page.getByText(/不能为空|invalid|required/i)).toBeVisible();
    }

    const uniqueText = `Hardened E2E Post ${Date.now()}`;
    await postInput.fill(uniqueText);
    await Promise.all([publishButton.click(), publishButton.click()]);

    const feedRegion = page.getByTestId('feed-list').or(page.getByRole('main'));
    await expect(feedRegion.getByText(uniqueText)).toHaveCount(1);

    await page.reload();
    await expect(feedRegion.getByText(uniqueText)).toBeVisible();
  });

  test('XSS payloads in post content are rendered safely without script execution', async ({ page }) => {
    let dialogTriggered = false;
    page.on('dialog', async (dialog) => {
      dialogTriggered = true;
      await dialog.dismiss();
    });

    await page.goto('/');
    const postInput = page.getByRole('textbox', { name: /发帖|动态|说点什么|post|content/i });
    const publishButton = page.getByRole('button', { name: /发布|发送|post|publish/i });

    const xssPayload = `<img src=x onerror="window.__xssExecuted=true;alert(1)"> safe-marker-${Date.now()}`;
    await postInput.fill(xssPayload);
    await publishButton.click();

    const feedRegion = page.getByTestId('feed-list').or(page.getByRole('main'));
    await expect(feedRegion.getByText(/safe-marker-/)).toBeVisible();
    expect(dialogTriggered).toBe(false);

    const xssFlag = await page.evaluate(() => (window as unknown as { __xssExecuted?: boolean }).__xssExecuted);
    expect(xssFlag).toBeUndefined();
  });

  test('User submits private message and sees error feedback for missing recipient', async ({ page, request }) => {
    await request.post('/api/v1/posts', {
      headers: FINGERPRINT_HEADER,
      data: { content: `DM Target Seed ${Date.now()}` },
    });
    const feedRes = await request.get('/api/v1/feed', {
      headers: FINGERPRINT_HEADER,
      params: { limit: 1 },
    });
    const feedBody = await feedRes.json();
    const validUserId = feedBody.posts[0].user_id;

    await page.goto('/');
    const messageNav = page
      .getByRole('link', { name: /站内信|私信|messages/i })
      .or(page.getByRole('button', { name: /站内信|私信|messages/i }));
    await expect(messageNav.first()).toBeVisible();
    await messageNav.first().click();

    const recipientInput = page.getByLabel(/收件人|recipient/i);
    const messageInput = page.getByLabel(/私信内容|消息内容|message/i);
    const sendButton = page.getByRole('button', { name: /发送|send/i });

    await expect(recipientInput).toBeVisible();
    await expect(messageInput).toBeVisible();

    await recipientInput.fill('non-existent-user-99999');
    await messageInput.fill('Should fail');
    await sendButton.click();
    await expect(page.getByText(/未找到|不存在|not found|404/i)).toBeVisible();

    await recipientInput.fill(validUserId);
    await messageInput.fill(`Hardened DM ${Date.now()}`);
    await sendButton.click();
    await expect(page.getByText(/发送成功|已发送|sent|success/i)).toBeVisible();
  });

  test('UI displays graceful error state and recovers when feed API returns 500_DB_ERROR', async ({ page }) => {
    let failFeed = true;
    await page.route('**/api/v1/feed*', async (route) => {
      if (failFeed) {
        await route.fulfill({
          status: 500,
          contentType: 'application/json',
          body: JSON.stringify({ error: '500_DB_ERROR', message: 'Database unavailable' }),
        });
      } else {
        await route.continue();
      }
    });

    await page.goto('/');
    await expect(page.getByText(/加载失败|服务异常|error|retry|重试/i)).toBeVisible();

    failFeed = false;
    const retryButton = page.getByRole('button', { name: /重试|刷新|retry|reload/i });
    if (await retryButton.isVisible()) {
      await retryButton.click();
    } else {
      await page.reload();
    }

    const feedRegion = page.getByTestId('feed-list').or(page.getByRole('main'));
    await expect(feedRegion).toBeVisible();
  });
});

test.describe('X.com UI Redesign & Micro-interactions', () => {
  test('X.com responsive navigation preserves view switching and identity status', async ({ page }) => {
    await page.goto('/');

    const feedNav = page
      .getByRole('button', { name: /动态|feed|home/i })
      .or(page.getByRole('link', { name: /动态|feed|home/i }));
    const messagesNav = page
      .getByRole('button', { name: /站内信|私信|messages/i })
      .or(page.getByRole('link', { name: /站内信|私信|messages/i }));

    await expect(feedNav.first()).toBeVisible();
    await expect(messagesNav.first()).toBeVisible();

    const identityBadge = page.locator('.user-identity-box, .identity-display, [title*="指纹"], [data-testid="user-identity"]').first();
    await expect(identityBadge).toBeVisible();

    // Navigate to Direct Messages
    await messagesNav.first().click();
    await expect(page.getByLabel(/收件人|recipient/i)).toBeVisible();

    // Navigate back to Feed
    await feedNav.first().click();
    const feedRegion = page.getByTestId('feed-list').or(page.getByRole('main'));
    await expect(feedRegion).toBeVisible();
  });

  test('User can expand tweet comments thread and post a reply smoothly', async ({ page, request }) => {
    const seedPostText = `X Thread Seed ${Date.now()}`;
    await request.post('/api/v1/posts', {
      headers: FINGERPRINT_HEADER,
      data: { content: seedPostText },
    });

    await page.goto('/');
    const postCard = page.locator('.post-card, article').filter({ hasText: seedPostText }).first();
    await expect(postCard).toBeVisible();

    const commentToggleBtn = postCard.getByRole('button', { name: /评论|回复|comments?|reply/i }).first();
    await expect(commentToggleBtn).toBeVisible();
    await commentToggleBtn.click();

    const commentInput = page
      .getByPlaceholder(/说点什么|写下你的回复|写评论|comment|reply/i)
      .or(page.getByRole('textbox', { name: /回复|评论|comment/i }))
      .first();
    await expect(commentInput).toBeVisible();

    const replyContent = `Interactive Thread Comment ${Date.now()}`;
    await commentInput.fill(replyContent);

    const replySubmitBtn = page
      .getByRole('button', { name: /回复|发送|评论|submit|send/i })
      .filter({ hasNotText: /发帖|发布动态/i })
      .last();
    await replySubmitBtn.click();

    await expect(page.getByText(replyContent)).toBeVisible();
  });

  test('Direct message compose form handles validation and interactive feedback', async ({ page }) => {
    await page.goto('/');
    const messageNav = page
      .getByRole('link', { name: /站内信|私信|messages/i })
      .or(page.getByRole('button', { name: /站内信|私信|messages/i }));
    await messageNav.first().click();

    const recipientInput = page.getByLabel(/收件人|recipient/i);
    const messageInput = page.getByLabel(/私信内容|消息内容|message/i);
    const sendButton = page.getByRole('button', { name: /发送|send/i });

    await expect(recipientInput).toBeVisible();
    await expect(messageInput).toBeVisible();

    await recipientInput.fill('');
    await messageInput.fill('');
    await sendButton.click();
    await expect(page.getByText(/不能为空|required|empty/i)).toBeVisible();
  });

  test('Global layout and interactive controls apply modern responsive design attributes', async ({ page }) => {
    await page.goto('/');
    const mainView = page.getByTestId('feed-list').or(page.getByRole('main'));
    await expect(mainView).toBeVisible();

    const publishBtn = page.getByRole('button', { name: /发布|发送|post|publish/i }).first();
    await expect(publishBtn).toBeVisible();

    const btnStyles = await publishBtn.evaluate((el) => {
      const computed = window.getComputedStyle(el);
      return {
        cursor: computed.cursor,
        borderRadius: computed.borderRadius,
      };
    });
    expect(btnStyles.cursor).toBe('pointer');
    expect(btnStyles.borderRadius).not.toBe('0px');
  });
});
